import{_ as n,C as o,o as i,c as l,a2 as t,b as r,w as s,a as d,E as h,a3 as p}from"./chunks/framework.CZqXuAiL.js";const F=JSON.parse('{"title":"Hot Reload — OpenShield-L7","description":"How OpenShield-L7 hot-reloads config — the file watcher, per-file failure isolation, atomic swaps, reload events, and how API writes map to files.","frontmatter":{"title":"Hot Reload — OpenShield-L7","description":"How OpenShield-L7 hot-reloads config — the file watcher, per-file failure isolation, atomic swaps, reload events, and how API writes map to files."},"headers":[],"relativePath":"openshield-l7/user-guide/hot-reload.md","filePath":"openshield-l7/user-guide/hot-reload.md","lastUpdated":null}'),c={name:"openshield-l7/user-guide/hot-reload.md"};function k(g,e,u,f,y,m){const a=o("Mermaid");return i(),l("div",null,[e[1]||(e[1]=t('<h1 id="hot-reload" tabindex="-1">Hot Reload <a class="header-anchor" href="#hot-reload" aria-label="Permalink to &quot;Hot Reload&quot;">​</a></h1><p>OpenShield-L7 never needs a restart for config changes. A filesystem watcher (<code>notify</code>) watches <code>sites_dir</code> <strong>and</strong> <code>config.yaml</code>, debounced to ~300 ms, and every change goes through the same validate → persist → apply pipeline whether it came from an editor or the admin API.</p><hr><h2 id="the-file-lifecycle" tabindex="-1">The file lifecycle <a class="header-anchor" href="#the-file-lifecycle" aria-label="Permalink to &quot;The file lifecycle&quot;">​</a></h2>',4)),(i(),r(p,null,{default:s(()=>[h(a,{id:"mermaid-10",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20EDIT%5B%22Edit%20sites.d%2Ffoo.yaml%3Cbr%2F%3E(or%20API%20write)%22%5D%20--%3E%20WATCH%5B%22notify%20watcher%3Cbr%2F%3E~300%20ms%20debounce%22%5D%0A%20%20%20%20WATCH%20--%3E%20PARSE%5B%22Re-parse%20ONLY%20the%20changed%20file%22%5D%0A%20%20%20%20PARSE%20--%3E%20VALID%7B%22Valid%3F%22%7D%0A%20%20%20%20VALID%20--%3E%7C%22yes%22%7C%20SWAP%5B%22Atomic%20swap%20(ArcSwap)%3Cbr%2F%3Enew%20requests%20see%20new%20config%22%5D%0A%20%20%20%20VALID%20--%3E%7C%22no%22%7C%20KEEP%5B%22Last%20good%20config%20keeps%20running%3Cbr%2F%3Efailure%20logged%20%2B%20event%20emitted%22%5D%0A%20%20%20%20SWAP%20--%3E%20EVENT%5B%22config_reload%20event%20on%20the%20bus%22%5D%0A%20%20%20%20KEEP%20--%3E%20EVENT%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t(`<h3 id="changed-site-file" tabindex="-1">Changed site file <a class="header-anchor" href="#changed-site-file" aria-label="Permalink to &quot;Changed site file&quot;">​</a></h3><p>Only that file is re-parsed and validated. On success the new config is swapped in atomically (<code>ArcSwap</code>): in-flight requests finish on the old snapshot, new requests see the new one — no downtime. Inspectors and throttlers are rebuilt; <strong>limiter counters for unchanged rules are preserved</strong> (a reload doesn&#39;t reset someone&#39;s rate-limit window).</p><h3 id="invalid-edit-—-failure-isolation" tabindex="-1">Invalid edit — failure isolation <a class="header-anchor" href="#invalid-edit-—-failure-isolation" aria-label="Permalink to &quot;Invalid edit — failure isolation&quot;">​</a></h3><p>A YAML error, a bad regex, a missing cert — the failure is logged and the <strong>last good config keeps running</strong>. One bad file never affects other sites; a broken file at startup is skipped the same way (logged, other files still load). This is the core promise: you can edit production files live without taking unrelated sites down.</p><p>Watch the failure surface in real time:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -sN</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:9090/api/v1/events/stream</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># data: {&quot;kind&quot;:&quot;config_reload&quot;,&quot;applied&quot;:[],&quot;failed&quot;:[[&quot;sites.d/broken.yaml&quot;,&quot;origin.url: &#39;http://&#39;: missing host&quot;]]}</span></span></code></pre></div><h3 id="the-reload-event" tabindex="-1">The reload event <a class="header-anchor" href="#the-reload-event" aria-label="Permalink to &quot;The reload event&quot;">​</a></h3><p>Every reload finishes with a <code>config_reload</code> event on the bus:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;kind&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;config_reload&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> &quot;applied&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;site-id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> &quot;failed&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sites.d/bad.yaml&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;yaml error: ...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]]}</span></span></code></pre></div><p>Also returned synchronously by <code>POST /api/v1/reload</code>. A non-empty <code>failed</code> array is the alert worth wiring into a dashboard or notification — it means &quot;an edit did not take.&quot;</p><h3 id="deleted-site-file" tabindex="-1">Deleted site file <a class="header-anchor" href="#deleted-site-file" aria-label="Permalink to &quot;Deleted site file&quot;">​</a></h3><p>The site is disabled (its runtime is kept for stats) or removed, depending on how it disappeared. <code>DELETE /api/v1/sites/{id}</code> removes both the file and the live registry entry.</p><h3 id="config-yaml-changes" tabindex="-1"><code>config.yaml</code> changes <a class="header-anchor" href="#config-yaml-changes" aria-label="Permalink to &quot;\`config.yaml\` changes&quot;">​</a></h3><p>Validated, then hot-applied. Two caveats:</p><ul><li><strong>Listener addresses, <code>data_dir</code>, <code>sites_dir</code></strong> apply to new connections / next restart — the process does not rebind sockets or move directories at runtime.</li><li><strong>Admin tokens</strong> are re-read from the live config on every request, so rotation is instant for new requests; already-accepted admin/API connections keep the old view.</li></ul><h3 id="site-id-assignment" tabindex="-1">Site <code>id</code> assignment <a class="header-anchor" href="#site-id-assignment" aria-label="Permalink to &quot;Site \`id\` assignment&quot;">​</a></h3><p>A new file with <code>id: &quot;&quot;</code> (or omitted) gets a uuid assigned by the loader, and the file is <strong>rewritten with it</strong> (atomic tmp+rename). The id is what API paths, metrics, and events reference.</p><hr><h2 id="api-writes-vs-file-edits-—-one-pipeline" tabindex="-1">API writes vs file edits — one pipeline <a class="header-anchor" href="#api-writes-vs-file-edits-—-one-pipeline" aria-label="Permalink to &quot;API writes vs file edits — one pipeline&quot;">​</a></h2><p>The admin API mutates the same files through the config store (validate → write <code>tmp</code> + atomic <code>rename</code> → hot-apply):</p><table tabindex="0"><thead><tr><th>API call</th><th>File effect</th></tr></thead><tbody><tr><td><code>POST /api/v1/sites</code></td><td>New <code>sites.d/&lt;id&gt;.yaml</code> (id assigned if empty, file rewritten with it)</td></tr><tr><td><code>PUT /api/v1/sites/{id}</code></td><td>Full replace of that file</td></tr><tr><td><code>PATCH /api/v1/sites/{id}</code></td><td>JSON merge-patch applied over the current config, result persisted</td></tr><tr><td><code>DELETE /api/v1/sites/{id}</code></td><td>File removed; site removed from the live registry</td></tr><tr><td><code>POST /api/v1/sites/{id}/enable</code> / <code>disable</code></td><td>Flips <code>enabled:</code> in the file</td></tr><tr><td><code>PUT /api/v1/global</code></td><td>Replaces <code>config.yaml</code> (validated first)</td></tr></tbody></table><p>A validation failure anywhere returns <strong>all</strong> collected errors (HTTP 400 with a <code>details</code> array) and leaves the running config untouched.</p><p>The interplay to remember:</p><ul><li><strong>Files are the source of truth.</strong> API writes persist to disk immediately; a file edit and an API write race on the same lock-free swap — last valid write wins.</li><li><strong>Out-of-band sync</strong> (rsync, Ansible, git pull into <code>sites.d/</code>) is picked up by the watcher like any edit. If you want an explicit barrier after a batch copy, call <code>POST /api/v1/reload</code> and inspect the report.</li><li><strong>Cert rotation</strong> is a file event too: write the new PEMs, touch the site file (or call <code>/reload</code>) — new TLS connections use the new cert. The SNI cert map also rebuilds hourly on its own.</li></ul><hr><h2 id="operator-checklist" tabindex="-1">Operator checklist <a class="header-anchor" href="#operator-checklist" aria-label="Permalink to &quot;Operator checklist&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. Validate before/after edits, without touching the running proxy</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openshield-l7</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --root</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/openshield-l7</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. Force a full re-read after out-of-band changes</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:9090/api/v1/reload</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. Watch what applied and what failed</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -sN</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:9090/api/v1/events/stream</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config_reload</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Hot reload covers <strong>configuration</strong>, not the binary. Upgrading the executable itself is a <code>systemctl restart</code> — see <a href="./../getting-started/installation#upgrade">Installation → Upgrade</a>.</p></div>`,28))])}const b=n(c,[["render",k]]);export{F as __pageData,b as default};
